        const operand = std.fmt.parseInt(i32, operand_str, 10) catch return ArgumentError.SyntaxError;

        if (std.mem.eql(u8, op, "plus")) {
            result += operand;
        } else if (std.mem.eql(u8, op, "minus")) {
            result -= operand;
        } else if (std.mem.eql(u8, op, "multiplied")) {
